    revokeMandate: {
        parameters: {
            query?: never;
            header: {
                /** @description Client-generated UUID; REQUIRED on every mutating call. Replays return the byte-identical stored response without re-executing the side effect; the same key with a different body is a 409 `idempotency_conflict`. Scoped to `(merchant, livemode, actor, endpoint, key)`. `livemode` is part of the scope, so the same key used in test and in live is two independent records and never replays one mode's response into the other. */
                "Idempotency-Key": components["parameters"]["IdempotencyKey"];
            };
            path: {
                /** @description The mandate id, e.g. `mnd_...`. */
                id: components["parameters"]["MandateId"];
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": components["schemas"]["MandateRevocation"];
            };
        };
        responses: {
            /** @description The mandate after revocation, carrying `state.revoked_at`. Returned rather than an empty body so a caller sees what the mandate had spent at the moment its authority ended. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Mandate"];
                };
            };
            400: components["responses"]["BadRequest"];
            401: components["responses"]["Unauthorized"];
            /** @description The revocation was not authorized — the signature did not verify against the mandate's principal key, and the caller is neither the owning merchant nor the mandate's own agent (`auth`). */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description No such mandate for this caller. */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            409: components["responses"]["Conflict"];
            /** @description Well-formed but not actionable — `mandate_id` does not match the path, or the signed `revoked_at` is outside the freshness window (`mandate`). */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            429: components["responses"]["TooManyRequests"];
            500: components["responses"]["ServerError"];
        };
    };
